/** Query parameters that carry feed URLs in a shared subscription link. */
const FEED_PARAM = "feed";
const FEEDS_PARAM = "feeds";

/**
 * Feed URLs carried by a shared link.
 *
 * Links generated by the app repeat `feed` (`?feed=<url>&feed=<url>`). A single
 * `feeds` parameter holding whitespace- or comma-separated URLs is accepted too,
 * so a hand-written link works as well.
 */
export function feedUrlsFromSearch(search: string): string[] {
  const params = new URLSearchParams(search);
  const values = [
    ...params.getAll(FEED_PARAM),
    ...params.getAll(FEEDS_PARAM).flatMap((value) => value.split(/[\s,]+/)),
  ];
  const urls: string[] = [];
  for (const value of values) {
    const trimmed = value.trim();
    if (trimmed !== "" && !urls.includes(trimmed)) urls.push(trimmed);
  }
  return urls;
}

/** A link that subscribes the reader to every given feed when they open it. */
export function subscriptionLink(feedUrls: string[], baseUrl: string): string {
  const url = new URL(baseUrl);
  url.search = "";
  url.hash = "";
  for (const feedUrl of feedUrls) url.searchParams.append(FEED_PARAM, feedUrl);
  return url.toString();
}
